const IGNORE_SHEETS = ["NON PPN OKTOBER","REKAP CV AMERTA","REKAP"];

// ─── BRAND COLORS (from logo) ─────────────────────────────────────────────────
const NAVY  = "#1B3D8F";
const BLUE2 = "#2E5FC2";
const TEAL  = "#0D9488";
const AMBER = "#D97706";
const RED   = "#DC2626";
const PURP  = "#7C3AED";
const CHART_COLORS = [NAVY, TEAL, AMBER, "#2E5FC2", RED, PURP, "#0891B2","#059669","#9333EA","#EA580C"];

const STORAGE_KEY = "amerta_monthly_data";
const BUDGET_KEY  = "amerta_budget_data";
const MONTH_ORDER = ["JANUARI","FEBRUARI","MARET","APRIL","MEI","JUNI","JULI","AGUSTUS","SEPTEMBER","OKTOBER","NOVEMBER","DESEMBER"];

function buildData(stored) {
  const months = Object.keys(stored);
  if (!months.length) return null;
  months.sort((a, b) => {
    const ai = MONTH_ORDER.findIndex(m => a.toUpperCase().includes(m));
    const bi = MONTH_ORDER.findIndex(m => b.toUpperCase().includes(m));
    return (ai === -1 ? 99 : ai) - (bi === -1 ? 99 : bi);
  });
  const allRows = months.flatMap(m =>
    stored[m].map(r => ({ ...r, date: r.date ? new Date(r.date) : null }))
  );
  return { allRows, months };
}

